import type { Metadata } from 'next';
import { SITE_NAME, withBase } from './site';

interface PageMeta {
  readonly title: string;
  readonly description: string;
  /** Route path with trailing slash, e.g. "/leafy/". The base path is added here, since metadataBase is the bare origin. */
  readonly path: string;
}

/** The one share image (generated by scripts/generate-brand-assets.tsx). */
export const OG_IMAGE = {
  url: withBase('/og.png'),
  width: 1200,
  height: 630,
  alt: 'Rivertide: You speak naturally. Rivertide writes clearly. Leafy, a green pixel sprout, smiles beside the words.',
} as const;

/** Per-page title, description, canonical URL and Open Graph fields. */
export function pageMetadata({ title, description, path }: PageMeta): Metadata {
  return {
    title,
    description,
    alternates: { canonical: withBase(path) },
    openGraph: { title: `${title} · ${SITE_NAME}`, description, url: withBase(path), images: [OG_IMAGE] },
    twitter: { card: 'summary_large_image', images: [OG_IMAGE.url] },
  };
}
